SELECT s.s_store_id, s.s_store_name, i.i_brand, td.t_shift, SUM(sr.sr_return_amt_inc_tax) AS total_return_amount, SUM(sr.sr_fee) AS total_fee, SUM(sr.sr_net_loss) AS total_net_loss, AVG(sr.sr_return_quantity) AS avg_return_qty, CASE WHEN SUM(sr.sr_net_loss) > 10000 THEN 'High Loss' WHEN SUM(sr.sr_net_loss) BETWEEN 5000 AND 10000 THEN 'Moderate Loss' WHEN SUM(sr.sr_net_loss) BETWEEN 0 AND 5000 THEN 'Low Loss' ELSE 'Profit' END AS loss_category, DENSE_RANK() OVER (PARTITION BY td.t_shift ORDER BY SUM(sr.sr_net_loss) DESC) AS loss_rank FROM store_returns sr JOIN store s ON sr.sr_store_sk = s.s_store_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk GROUP BY s.s_store_id, s.s_store_name, i.i_brand, td.t_shift HAVING SUM(sr.sr_return_amt_inc_tax) > 0 ORDER BY loss_rank
